import{r as Z,j as s,c as Le}from"./vendor.js";import{s as we,e as Ge,a as xe,b as Ee,u as Se,c as ye,p as $e,L as e}from"./content.js";import"./reading.js";(function(){const t=document.createElement("link").relList;if(t&&t.supports&&t.supports("modulepreload"))return;for(const V of document.querySelectorAll('link[rel="modulepreload"]'))m(V);new MutationObserver(V=>{for(const $ of V)if($.type==="childList")for(const Y of $.addedNodes)Y.tagName==="LINK"&&Y.rel==="modulepreload"&&m(Y)}).observe(document,{childList:!0,subtree:!0});function i(V){const $={};return V.integrity&&($.integrity=V.integrity),V.referrerPolicy&&($.referrerPolicy=V.referrerPolicy),V.crossOrigin==="use-credentials"?$.credentials="include":V.crossOrigin==="anonymous"?$.credentials="omit":$.credentials="same-origin",$}function m(V){if(V.ep)return;V.ep=!0;const $=i(V);fetch(V.href,$)}})();const re={};re.pow=[{label:"Book pages",value:"Lesson 1-1, Powers of Powers, book pp. 2-6."},{label:"Power of a power rule",value:"(a^m)^n = a^(m x n). To find the power of a power, multiply the exponents. Example: (5^4)^2 = 5^8 and (7^-2)^5 = 7^-10. Note: (a^m)^n is not the same as a^(m^n), and (a^m + b^n)^k is not a^(mk) + b^(nk)."},{label:"Power of a product and of a quotient",value:"(a^m x b^n)^k = a^(mk) x b^(nk). (a^m / b^n)^k = a^(mk) / b^(nk), with b not equal to 0. Example: (2^3 x 3^4)^3 = 2^9 x 3^12: multiply each exponent by the outside power."},{label:"Laws of exponents (review)",value:"a^m x a^n = a^(m+n). a^m / a^n = a^(m-n). (a x b)^m = a^m x b^m. (a/b)^m = a^m / b^m. a^-n = 1 / a^n. a^0 = 1 (a not 0). Also (-a)^n = a^n if n is even, and = -a^n if n is odd."},{label:"Example 1 (1) from the book",value:"Simplify (2^11)^2 x 2^3 / ((2^6)^3 x 2^4). Step 1: apply the power of a power rule: 2^22 x 2^3 / (2^18 x 2^4). Step 2: add exponents on each side: 2^25 / 2^22. Step 3: subtract: 2^3 = 8."},{label:"Example 4 (tiles) idea",value:"Number of tiles = area of the room floor / area of one tile. Room side = 2x^3y^2, so area = 4x^6y^4. Tile side = xy^2, so area = x^2y^4. Number of tiles = 4x^6y^4 / x^2y^4 = 4x^4 tiles."},{label:"Lesson assessment answers (p. 5)",value:"1) (a^4)^7 = a^28, choice (c). 2) (3^8)^0 = 1, choice (c). 3) (3^4)^2 x 3^5 = 3^8 x 3^5 = 3^13, choice (b). 5) x^2 x (x^5)^2 = x^2 x x^10 = x^12, choice (b). 7) If 2^x = 5 then 8^x = (2^x)^3 = 125, choice (a). 9) Spot the mistake: (a^2)^3 x a^4 = a^6 x a^4 = a^10, so Asmaa is correct and Khaled is wrong (he multiplied 2 x 3 and then added wrongly)."},{label:"Problems 14 and 19 (p. 6)",value:"14) If 3^a = 2: 9^a = (3^a)^2 = 4 and 27^a = (3^a)^3 = 8, so the value is 4 + 8 = 12. 19) a = 5^30 = 25^15, b = 3^45 = 27^15, c = 2^60 = 16^15. Same exponent 15, so compare the bases 16 < 25 < 27. Ascending order: c, a, b."},{label:"Tip for the exam",value:"First write every base as a prime number (4 = 2^2, 9 = 3^2, 18 = 2 x 3^2). Then use the power rules one at a time and group equal bases."}];re.expeq=[{label:"Book pages",value:"Lesson 1-2, Exponential Equations, book pp. 7-13."},{label:"Definition",value:"An exponential equation has the variable in the exponent. 2^x = 8 and 3^(x-4) = 1/9 are exponential. x^2 = 9 and x - 7 = 3^2 are not. This year we study a^x = b where a > 0 and a is not 1."},{label:"Main rule: equality of powers",value:"If a^x = a^y where a > 0 and a is not 1, then x = y. Examples: if 3^x = 3^4 then x = 4. If 5^x = 125 then 5^x = 5^3 so x = 3. Factorize to find the base: 125 = 5^3, 32 = 2^5, 81 = 3^4."},{label:"Special cases (Note box)",value:"If a^x = 1 (a > 0, a not 1) then x = 0. If a^x = b^x (a, b > 0, a not b) then x = 0. Also (a/b)^n = (b/a)^-n."},{label:"Example 1 from the book",value:"(1) 3^(x+1) = 81 = 3^4, so x + 1 = 4, x = 3. (2) 2^(x-7) = 1/32 = 2^-5, so x - 7 = -5, x = 2. (3) (2/3)^(x+2) = 27/8 = (3/2)^3 = (2/3)^-3, so x + 2 = -3, x = -5. Check the answer by substituting back: 3^(3+1) = 3^4 = 81, correct."},{label:"Example 2 from the book",value:"(1) 9^(x+2) = 3^x. Write 9 = 3^2: 3^(2x+4) = 3^x, so 2x + 4 = x, x = -4. (2) 125^(x+1) = 625^(x-1). Write both with base 5: 5^(3x+3) = 5^(4x-4), so 3x + 3 = 4x - 4, x = 7. (4) 2^(x^2) = 16^(3-x) = 2^(12-4x), so x^2 + 4x - 12 = 0, (x + 6)(x - 2) = 0, x = -6 or x = 2."},{label:"Example 3 from the book",value:"(1) 4^(x^2-9) = 1 = 4^0, so x^2 - 9 = 0, x = 3 or x = -3. (2) 2^(x+1) = 3^(x+1): different bases, same exponent, so x + 1 = 0 and x = -1."},{label:"Example 4 from the book",value:"Find n: (1) 2^n x 9^(n+1) / 18^n = 3^n. Write 9 = 3^2 and 18 = 2 x 3^2: the powers of 2 cancel, leaving 3^(2n+2-2n) = 3^2 = 3^n, so n = 2. (2) 12^(n-1) / (2^(n-1) x 3^(n-1)) = 1: since 12 = 2^2 x 3, this becomes 2^(n-1) = 1, so n - 1 = 0 and n = 1."},{label:"Self-evaluation answers (p. 8)",value:"1) 2^(x-2) = 8 = 2^3, so x = 5. 2) (1/2)^(2x-1) = 32: (1/2)^(2x-1) = 2^5 = (1/2)^-5, so 2x - 1 = -5, x = -2. 3) 125/27 = (5/3)^3 = (3/5)^-3, so x + 2 = -3, x = -5."},{label:"Warm-up from the lesson opening",value:"Bacteria double every hour, so after n hours there are 2^n cells. 2^n = 1024 = 2^10, so n = 10 hours. The rectangle with area 63 cm^2 and sides 7 and 3^x: 7 x 3^x = 63, 3^x = 9, so x = 2."},{label:"Tip for the exam",value:"Steps: (1) write both sides with the same base, (2) equate the exponents, (3) solve the new equation, (4) check by substitution. If the equation becomes quadratic, you may have two solutions."}];re.quadfn=[{label:"Book pages",value:"Lesson 2-1, Quadratic Function, book pp. 14-21."},{label:"Definition and standard form",value:"A quadratic function is a second-degree function in one variable. Its graph is a curve called a parabola, symmetric about a vertical line called the axis of symmetry, which passes through the vertex. Standard form: f(x) = ax^2 + bx + c, a not 0. The domain is R. The x-coordinate of the vertex is x = -b/(2a). The y-coordinate is f(-b/(2a)). The y-intercept is c, because f(0) = c."},{label:"Max and min",value:"If a > 0 the parabola opens upward and the function has a minimum value at the vertex, equal to f(-b/2a). If a < 0 it opens downward and has a maximum value f(-b/2a)."},{label:"Vertex form",value:"f(x) = a(x - h)^2 + k, a not 0. The vertex is (h, k), the axis of symmetry is x = h, and the minimum (a > 0) or maximum (a < 0) value is k. Careful with signs: f(x) = 5 - 2(x + 1)^2 = -2(x - (-1))^2 + 5 has vertex (-1, 5)."},{label:"How to draw the graph (4 steps)",value:"1) Find x = -b/2a for the vertex. 2) Choose values of x on both sides of it (about 2 on each side). 3) Make a table of x and f(x). 4) Plot the points and draw a smooth curve. Example 1 (1): f(x) = x^2 - 2x - 3, vertex x = 1, table gives (-2,5), (-1,0), (0,-3), (1,-4), (2,-3), (3,0), (4,5). The curve opens up, minimum value -4. Example 1 (2): f(x) = -x^2 + 6x - 5, vertex x = 3, vertex (3, 4), opens down, maximum value 4."},{label:"Example 2 from the book",value:"(1) f(x) = x^2 - 4x + 3: x = 4/2 = 2, f(2) = -1, vertex (2, -1), y-intercept (0, 3), opens up, minimum -1. (2) g(x) = -x^2 + 9: x = 0, vertex (0, 9), y-intercept (0, 9), opens down, maximum 9."},{label:"Example 4 from the book",value:"f(x) = 2(x - 3)^2 + 1, point (b, 9) lies on the curve. Vertex (3, 1), a = 2 > 0 so minimum value 1. Substitute: 2(b - 3)^2 + 1 = 9, (b - 3)^2 = 4, b - 3 = 2 or -2, so b = 5 or b = 1."},{label:"Example 5 (football)",value:"h(t) = -4.9t^2 + 19.6t. Vertex t = -19.6 / (2 x -4.9) = 2 seconds. h(2) = 19.6 m. So the maximum height is 19.6 meters and the ball reaches it after 2 seconds. Do not use negative values of t."},{label:"Lesson assessment answers (p. 20)",value:"1) f = 2(x-3)^2 + 1: vertex (3, 1), choice (d). 2) 2x^2 - 8x + 7: h = 8/4 = 2, choice (a). 3) y-intercept of x^2 - 3x - 5 is (0, -5), choice (a). 4) x^2 - 6x + 14: vertex x = 3, minimum = 9 - 18 + 14 = 5, choice (b). 5) For a quadratic, the coefficient of x^3 must be 0: a + 4 = 0, a = -4, choice (a). 6) -12/(2a) = -2, a = 3, choice (a). 8) The curve has vertex (2, 4), so f(x) = (x - 2)^2 + 4, choice (c)."},{label:"Applying problems (pp. 21)",value:"10) h(t) = -(t - 4)^2 + 16: vertex (4, 16). Maximum height 16 m after 4 s, and the ball returns to the ground at t = 8 s. 11) h(t) = -2t(t - 6): zeros at t = 0 and 6, vertex at t = 3, h(3) = 18 m. 18 > 15, so the arrow passes over the branch. 12) f = x^2 - 2x + k + 1: vertex V = (1, k). A = (1, 0). OA = 1 = (1/2) VA, so VA = 2 and k = 2. Point C is the y-intercept (0, k + 1) = (0, 3). 13) f = x^2 - 10x + k: vertex (5, k - 25). Distance from the origin 13: 25 + (k - 25)^2 = 169, so (k - 25)^2 = 144 and k = 37 or k = 13."},{label:"Tip for the exam",value:"Always write a, b, c first. Find the vertex before the table. For max/min questions, just give the y-coordinate of the vertex and say whether it is maximum (a < 0) or minimum (a > 0)."}];re.zeros=[{label:"Book pages",value:"Lesson 2-2, Set of Real Zeros of Polynomial Functions, book pp. 22-26."},{label:"Polynomial functions",value:"f(x) = a0 + a1x + a2x^2 + ... + anx^n where all exponents are positive integers (or zero) and the last coefficient is not 0. n is the degree. Examples: x^3 - sqrt(2)x + 1 (degree 3, cubic), 2x - x^2 (degree 2, quadratic), 9 - 4x (degree 1, linear), 7 (degree 0, constant). f(x) = 0 is the zero polynomial and has no degree. Not polynomials: 1/x, 4^x, -2x^-3."},{label:"Zeros of a function",value:"The real zeros are the real values of x that make f(x) = 0. The set of zeros is {x : f(x) = 0, x in R}. If f(a) = 0 then: a is a zero of f, x = a is a solution of f(x) = 0, and (x - a) is a factor of f(x). To find the zeros, solve f(x) = 0."},{label:"Special cases",value:"If f(x) = a where a is a non-zero constant, the set of zeros is the empty set. If f(x) = 0 (the zero function), the set of zeros is R."},{label:"Example 1 from the book",value:"(1) 3x - 6 = 0, x = 2, set {2}. (2) x^2 - 25 = 0, x = 5 or -5, set {-5, 5}. (3) x^2 - x - 12 = (x + 3)(x - 4) = 0, set {-3, 4}. (4) x^3 + 2x^2 - 15x = x(x + 5)(x - 3) = 0, set {0, -5, 3}. (5) 3x^2 + 12 = 0 gives x^2 = -4, no real roots, empty set. (6) 27x^3 + 125 = 0, x^3 = -125/27, x = -5/3, set {-5/3}."},{label:"Zeros from a graph",value:"If the curve of f meets the x-axis at (a, 0), then a is a zero of f. The number of different real zeros equals the number of points where the curve meets the x-axis. Example 2: the three curves in the book meet the x-axis at {1}, {-1, 0, 2} and {-2, 2}."},{label:"Example 3 from the book",value:"If -3 is a zero of f(x) = 2x^2 + bx + 3, find b and f(4). f(-3) = 0: 18 - 3b + 3 = 0, so b = 7. Then f(x) = 2x^2 + 7x + 3 and f(4) = 32 + 28 + 3 = 63."},{label:"Lesson assessment answers (p. 25)",value:"1) -3x = 0 gives {0}, choice (c). 2) x^2 + 25 has no real zeros, choice (d). 4) Zeros {-2, 0}: f(x) = x^2 + 2x, choice (c). 5) g(x) = 3 has no zeros, choice (c). 6) If (x + 3) is a factor then p(-3) = 0, choice (d). 7) If 1 is a zero then p(1) = 0, choice (c). 8) Zeros {-3, 3} of x^2 + k: k = -9, choice (c)."},{label:"Problem 9 answers",value:"1) {8}. 2) {6, -6}. 3) empty set (4x^2 + 9 = 0 has no real solution). 4) {0}. 5) x^3 - x = x(x - 1)(x + 1): {0, 1, -1}. 6) x^2 - 3x + 2 = (x - 1)(x - 2): {1, 2}. 7) 3x(x - 4): {0, 4}. 8) x^3 = -64: {-4}. 9) 2x^2 - 7x + 6 = (2x - 3)(x - 2): {3/2, 2}."},{label:"Problems 10 to 14 answers",value:"10) f(-2) = 0: 4 - 2b - 14 = 0, b = -5. 11) p(-7) = 0: 98 - 42 + c = 0, c = -56. p(x) = 2x^2 + 6x - 56 = 2(x + 7)(x - 4), set {-7, 4}. 12) g(3) = 0: 9 - 3(k - 5) - 5k = 0, 24 = 8k, k = 3. g(x) = x^2 + 2x - 15 = (x + 5)(x - 3), set {-5, 3}. 13) -3t^2 + 18t + 165 = 0 gives t^2 - 6t - 55 = 0, (t - 11)(t + 5) = 0, so on day 11. 14) (1) x^3 - 5x^2 - 4x + 20 = (x - 5)(x - 2)(x + 2): {5, 2, -2}. (2) 2x^3 - x^2 - 8x + 4 = (2x - 1)(x - 2)(x + 2): {1/2, 2, -2}. (3) x^2 - 2x - 6 = 0 by the formula: {1 + sqrt(7), 1 - sqrt(7)}."},{label:"Opening problem",value:"c(t) = 9 - t^2/4 = 0, so t^2 = 36 and t = 6. The medicine vanishes after 6 hours."}];re.rdomain=[{label:"Book pages",value:"Lesson 2-3, Rational Algebraic Functions, book pp. 27-32."},{label:"Rational algebraic fraction",value:"A ratio of two polynomials p(x)/q(x) with q(x) not 0. It is defined for all real numbers except the zeros of the denominator. Example: (x^2 - 1)/(x + 2) is defined everywhere except x = -2. In a rational function both numerator and denominator must be polynomials (no roots or fractional exponents)."},{label:"Domain",value:"The domain of f = p/q is D_f = R - {x : q(x) = 0}. Steps: set the denominator equal to zero, solve, and remove those values from R. Find the domain BEFORE simplifying. Example: for f(x) = x^2/(x^2 - 9), f is undefined at x = 3 and x = -3 (so Hanan is correct in the Think and Discuss box)."},{label:"Example 1 from the book",value:"(1) (x - 3)/(x^2 - 3x + 2): x^2 - 3x + 2 = (x - 2)(x - 1) = 0, so the fraction is undefined when x is in {1, 2}. (2) (x + 4)/(x^2 + 16): x^2 = -16 has no real solution, so the set of values that make it undefined is empty and the domain is R."},{label:"Example 2 from the book",value:"f(x) = (x^2 - 25)/(x - 5): D_f = R - {5}. f(5) is undefined, f(-5) = 0/(-10) = 0. g(x) = (x^2 - 2x)/(x^2 + x - 6): x^2 + x - 6 = (x - 2)(x + 3), so D_g = R - {-3, 2}. g(-3) is undefined, g(0) = 0."},{label:"Simplifying (Example 3)",value:"Simplify by cancelling common factors, but the function keeps its domain from before cancellation. f(x) = (x^2 + 2x - 15)/(x^2 - 5x + 6) = (x - 3)(x + 5)/((x - 2)(x - 3)). D_f = R - {2, 3}. Simplest form: f(x) = (x + 5)/(x - 2). f(1) = -6. f(2) and f(3) cannot be found because 2 and 3 are not in the domain."},{label:"Zeros of a rational function",value:"The set of zeros of p/q = {x : p(x) = 0, q(x) not 0}: the zeros of the numerator except the zeros of the denominator. Example 4: f = (x^2 - 7x + 12)/(x^2 - x - 6) = (x - 3)(x - 4)/((x - 3)(x + 2)). Zeros of numerator {3, 4}, zeros of denominator {3, -2}, so the zeros of f are {4}. Check: f(4) = 0."},{label:"Example 5 (solving f(x) = number)",value:"(1) f(x) = (x^2 - 4)/(x - 2) = x + 2 with D_f = R - {2}. f(x) = 5 gives x = 3, which is in D_f, so the solution set is {3}. (2) g(x) = (x^2 + 2x - 3)/(x - 1) = x + 3 with D_g = R - {1}. g(x) = 4 gives x = 1, which is NOT in the domain, so the solution set is the empty set."},{label:"Lesson assessment answers (p. 31)",value:"1) (x - 1)/(x + 2) is undefined at x = -2, choice (d). 2) (x + 3)/(x - 2) equals zero at x = -3, choice (a). 3) x^2 + 4 is never zero, so the domain is R, choice (d). 4) (x^2 - 25)/7 is a polynomial over a constant, domain R, choice (a). 5) f = (x^2 - 2x)/(x^2 + 2x): zeros of numerator {0, 2}, of denominator {0, -2}, so the set of zeros is {2}, choice (b). 6) Domain R - {-2} for 2x/(x - a) means a = -2, choice (d). 7) x = 3 is a zero of (x^2 - x + a)/(x + 2): 9 - 3 + a = 0, a = -6, choice (a). 8) Spot the mistake: Amal is correct. f(x) = 4(x + 3)/((x + 3)(x - 4)) = 4/(x - 4), but the domain must be taken before simplifying: R - {-3, 4}. Magdy wrote R - {4}, which is wrong."},{label:"Problem 9: simplest form and domain",value:"1) (2x - 5)/(5 - 2x) = -1, domain R - {5/2}. 2) (x - 4)/(x^2 - 16) = 1/(x + 4), domain R - {4, -4}. 3) (x - 1)(x - 2)/(3(x - 1)) = (x - 2)/3, domain R - {1}. 4) 6(x + 2)/((2x + 3)(x + 2)) = 6/(2x + 3), domain R - {-3/2, -2}. 5) (3x + 4)(x + 4)/((x - 7)(x + 4)) = (3x + 4)/(x - 7), domain R - {7, -4}. 6) (2x - 5)(2x + 1)/(-(2x - 5)(x + 3)) = -(2x + 1)/(x + 3), domain R - {5/2, -3}."},{label:"Problems 10 to 14",value:"10) Zeros: 1) {-2}. 2) {3} (x = -3 is excluded). 3) empty set (3 is a zero of the numerator but also of the denominator). 4) {1/2}. 5) {1, 2}. 6) {-1/2}. 11) Domain R - {6} means x^2 - ax + 36 = 0 only at x = 6: 36 - 6a + 36 = 0, a = 12. 12) f(2) is undefined, so b = 2. f(5) = (5 + a)/3 = 2, so a = 1. 13) f(x) = (2x - 3)(x + 5)/(2x - 3) = x + 5, domain R - {3/2}. x + 5 = 10 gives x = 5, solution set {5}. 14) g(x) = (x - 2)(x - 3)/(x - 2) = x - 3, domain R - {2}. x - 3 = -1 gives x = 2, not in the domain, so the solution set is empty. 15) Equal areas: k(x + 2) = 2x(2x + 4), so k = 4x. For x = 2, k = 8. For k = 4, x = 1."},{label:"Opening problem",value:"The speed is distance / time = (x^2 + 8x + 12)/(x^2 - x - 6) = (x + 2)(x + 6)/((x - 3)(x + 2)) = (x + 6)/(x - 3) km/h, for x not 3 and not -2."}];re.rcommon=[{label:"Book pages",value:"Lesson 2-4, Common Domain and Equivalent Rational Algebraic Functions, book pp. 33-37."},{label:"Common domain",value:"The common domain of two functions f and g is the intersection of their domains: D_f intersect D_g = R - (Z1 union Z2), where Z1 and Z2 are the sets of zeros of the two denominators. In words: all real numbers except the zeros of both denominators."},{label:"Example 1 from the book",value:"f(x) = (x^2 - 4x + 3)/(x^2 - x - 6) and g(x) = (x^2 - 9)/(x^2 - 5x + 6). Denominator of f: (x - 3)(x + 2), so D_f = R - {-2, 3}. Denominator of g: (x - 2)(x - 3), so D_g = R - {2, 3}. Common domain = R - {-2, 2, 3}."},{label:"Example 2 from the book",value:"f = (x^3 + 1)/(x^2 - 1): D_f = R - {1, -1}. g = 5/(x^2 + 4): D_g = R, because x^2 = -4 has no real solution. p = (2x^2 - 7x + 6)/(2x + 3): D_p = R - {-3/2}. Common domain of f, g and p = R - {-3/2, -1, 1}."},{label:"Equal (equivalent) functions",value:"Two rational functions are equal, f = g, only if BOTH conditions hold: (1) their domains are identical, D_f = D_g, and (2) f(x) = g(x) for every x in the domain (their simplest forms are identical). If the domains differ, the functions are not equal, even if the simplified rules match."},{label:"Example 3 from the book",value:"f = (x^2 - 3x)/(x^2 - 6x + 9) = x(x - 3)/(x - 3)^2, D_f = R - {3}, f(x) = x/(x - 3). g = 4x/(4x - 12) = 4x/(4(x - 3)), D_g = R - {3}, g(x) = x/(x - 3). Same domain and same rule, so f = g."},{label:"Example 4 from the book",value:"f = x/(x^2 - 2x) = x/(x(x - 2)): D_f = R - {0, 2}, f(x) = 1/(x - 2). g = (x^2 + 2x + 4)/(x^3 - 8) = (x^2 + 2x + 4)/((x - 2)(x^2 + 2x + 4)): D_g = R - {2}, g(x) = 1/(x - 2). The domains are different, but f(x) = g(x) for every x in the common domain R - {0, 2}. (They are not equal functions, since D_f is not D_g.)"},{label:"Lesson assessment answers (p. 36)",value:"1) f = 3/(x + 2), g = -1/(x - 2): common domain R - {-2, 2}, choice (c). 2) f = x/(x(x - 3)) = 1/(x - 3) with D_f = R - {0, 3}; g = 1/(x - 3) with D_g = R - {3}. f(x) = g(x) for all x in R - {0, 3}, choice (c). 3) The common domain is R - {-3} when the denominators vanish only at -3: k = -3, choice (b). 4) Doaa is correct: D_f = R - {-1, 5} and D_g = R - {0, 5} are different, so f is not equal to g. Iman only compared the simplified rules."},{label:"Problems 5 to 10 answers",value:"5) (1) R - {2, 3}. (2) f = (x - 5)(x + 4)/((x - 5)(x + 2)), D_f = R - {5, -2}; g = (x - 5)(x + 2)/((x - 3)(x + 2)), D_g = R - {3, -2}; common domain R - {-2, 3, 5}. 6) D_f = R, D_g = R - {3, -3}, D_k = R - {0, 3}; common domain R - {-3, 0, 3}. 7) (1) f = x/(x^2 - 4), g = 3x/(3(x^2 - 4)): same domain R - {2, -2}, same rule, so f = g. (2) f = x(x - 2)/(x - 2)^2 = x/(x - 2), D = R - {2}; g = x/(x - 2): f = g. (3) f = x(x + 2)/(x + 2)^2 = x/(x + 2), g = 6x/(6(x + 2)) = x/(x + 2): f = g. 8) (1) f = (x - 1)/(x + 4) with D_f = R - {4, -4}; g = (x - 1)/(x + 4) with D_g = R - {-3, -4}. Not equal, domains differ. (2) f = x/(x - 2), g = 1/(x - 2): the rules differ, so not equal. 9) (1) f = 1/(x + 1) and g = 1/(x + 1): equal for all x in R - {1, -1}. (2) f = (x + 1)/(x - 3), g = (x + 1)/(x - 3): equal for x in R - {0, 3}. (3) f = 1/(x - 4), g = 1/(x - 4): equal for x in R - {4, -4, -1}. 10) The four quantities are proportional: x/(x^2 - 3x) = (x + 3)/(x^2 - 9) holds for all x except 0, 3, -3, so x can be any real number in R - {0, 3, -3}."},{label:"Opening problem",value:"Girls: (x^2 - 5x)/(x^2 - 8x + 15) = x(x - 5)/((x - 3)(x - 5)) = x/(x - 3). Boys: (x^2 - x)/(x^2 - 4x + 3) = x(x - 1)/((x - 1)(x - 3)) = x/(x - 3). The simplified rules are the same, but the domains are different (x = 5 is excluded for girls, x = 1 for boys), so the average ages are equal only for x in R - {1, 3, 5}, not for all values of x."}];re.rops=[{label:"Book pages",value:"Lesson 2-5, Operations on Rational Algebraic Fractions, book pp. 38-47."},{label:"Adding and subtracting",value:"Steps: 1) Factorize numerators and denominators and simplify each fraction. 2) Find a common denominator and add or subtract the numerators. 3) Write the result in simplest form. Same denominator: a/c + b/c = (a + b)/c. Different denominators: a/b + c/d = (ad + cb)/(bd). The domain of a sum or difference is all real numbers except the values that make either denominator zero. Find the domain before simplifying."},{label:"Properties of addition",value:"Commutative, associative, zero is the additive identity, and every fraction p/q has an additive inverse: -p/q = (-p)/q = p/(-q)."},{label:"Example 1 from the book",value:"(1) (x^2 - 4)/(x^2 - x - 6) + (x^2 - 5x + 4)/(x^2 - 4x + 3) = (x - 2)(x + 2)/((x - 3)(x + 2)) + (x - 1)(x - 4)/((x - 1)(x - 3)). D_f = R - {3, -2, 1}. = (x - 2)/(x - 3) + (x - 4)/(x - 3) = (2x - 6)/(x - 3) = 2. (2) 2(x - 1)/((x - 1)(x - 2)) - 3(x + 1)/((x - 2)(x + 1)) = 2/(x - 2) - 3/(x - 2) = -1/(x - 2), with D_f = R - {1, 2, -1}."},{label:"Example 2 from the book",value:"f(x) = (2x + 4)/(x^2 - 4) + (3x + 3)/(x^2 - 1) = 2/(x - 2) + 3/(x - 1), D_f = R - {-2, 2, -1, 1}. = (2(x - 1) + 3(x - 2))/((x - 2)(x - 1)) = (5x - 8)/((x - 2)(x - 1)). f(3) = 7/2 = 3.5. f(-1) is undefined because -1 is not in the domain."},{label:"Multiplying",value:"Steps: 1) Factorize everything. 2) Cancel common factors between any numerator and any denominator. 3) Multiply numerators and denominators and simplify. a/b x c/d = ac/bd. Properties: commutative, associative, 1 is the multiplicative identity, and every fraction p/q (p not 0) has a multiplicative inverse q/p. The domain is all real numbers except the zeros of the denominators."},{label:"Example 3 from the book",value:"(1) (x^2 + x - 20)/(x - 3) x (2x^2 - 6x)/(x^2 + 3x - 10) = (x + 5)(x - 4)/(x - 3) x 2x(x - 3)/((x + 5)(x - 2)) = 2x(x - 4)/(x - 2), D_f = R - {3, -5, 2}. (2) (x + 3)(x - 2)/((x + 3)(x + 4)) x (x + 4)(x + 2)/((2 - x)(2 + x)) = (x - 2)/(2 - x) = -1, D_f = R - {-3, -4, 2, -2}. Remember 2 - x = -(x - 2)."},{label:"Reciprocal (multiplicative inverse)",value:"If f(x) is a rational function, its reciprocal is g(x) = 1/f(x). The domain of g is all real numbers except the values that make the numerator or the denominator of f zero. Example 4: f(x) = (x^2 + x - 2)/(x^2 - 3x - 10) = (x - 1)(x + 2)/((x + 2)(x - 5)). Then g(x) = (x + 2)(x - 5)/((x - 1)(x + 2)) = (x - 5)/(x - 1), D_g = R - {1, -2, 5}. g(-2) is undefined because -2 is not in D_g. If g(x) = 1/2 then (x - 5)/(x - 1) = 1/2, 2x - 10 = x - 1, x = 9, which is in D_g."},{label:"Dividing",value:"Dividing by a fraction means multiplying by its reciprocal: a/b divided by c/d = a/b x d/c (c not 0). Factorize first, then cancel. Example: (x^2 + 12x + 20)/(x^2 - 3x - 10) divided by (x^2 + 10x)/(x - 5) = (x + 2)(x + 10)/((x + 2)(x - 5)) x (x - 5)/(x(x + 10)) = 1/x. The domain also excludes the zeros of the divisor, because you cannot divide by zero."},{label:"Opening problem (Khaled)",value:"Add the two exam scores: (3x^2 + 16x + 21)/(x^2 + 5x + 6) + (5x^2 + 34x + 45)/(x^2 + 7x + 10). Factorize: (3x + 7)(x + 3)/((x + 2)(x + 3)) + (5x + 9)(x + 5)/((x + 2)(x + 5)) = (3x + 7)/(x + 2) + (5x + 9)/(x + 2) = (8x + 16)/(x + 2) = 8. The sum is 8, so Khaled gets an excellent grade (he needed at least 8). Also, in the Think and Discuss box, (x + 3)/(x + 3) = 1 only for x not equal to -3, so Sameh was not fully correct: the function is 1 only on its domain R - {-3}."},{label:"Tip for the exam",value:"Always: factorize, write the domain, then simplify. Never cancel terms that are added, only factors that are multiplied. Never forget to exclude values that make a divisor zero."}];re.rops.push({label:"Example 5 from the book (division)",value:"(1) f(x) = (x^2 + 2x + 1)/(1 - x^2) divided by (x^2 + 5x + 4)/(x^2 + 3x - 4) = (x + 1)^2/((1 - x)(1 + x)) x (x - 1)(x + 4)/((x + 1)(x + 4)) = (x - 1)/(1 - x) = -1, with D_f = R - {1, -1, -4}. (2) The second fraction is divided too: D_f = R - {1/2, -2, -4, -1/3}, and f(x) = (2x + 1)/(3x + 1) after simplifying."},{label:"Lesson assessment answers (pp. 42-43)",value:"1) (2 - x)/(x - 2) = -1, choice (a). 3) The fraction (x - 3)/(x + 2) is the reciprocal of (x + 2)/(x - 3), not its additive inverse, choice (c). 4) The reciprocal of (x - 2)/(x + 3) has domain R - {2, -3}, choice (c). 5) x/(x - 1) x (x^2 - 1)/x^2 = (x + 1)/x, choice (d). 6) Domain: exclude -3 and 5 (denominators) and 0 (the divisor is zero): R - {-3, 5, 0}, choice (d). 7) g is the reciprocal (x + 7)/(x - 5). g(k) = 3/2 gives 2k + 14 = 3k - 15, k = 29, choice (c). 8) 4/(3x) + 5/(3x) = 3/x, so [f]^-1 = x/3, choice (b)."},{label:"Problem 10 answers",value:"1) (5x - 10)/(x - 2) = 5. 2) (x^2 - 25)/(x - 5) = x + 5. 3) x/3 - 4/x = (x^2 - 12)/(3x). 4) 1/(x - 3) + 1/(x - 4) = (2x - 7)/((x - 3)(x - 4)). 5) x/(x + 3) divided by x^2/(x^2 + 3x) = 1. 6) 3(x - 2)/(5(x - 4)) x 10(x - 4)/(27(x - 2)) = 2/9."},{label:"Problems 11 to 16 (selected)",value:"11) (1) = x/(x + 2) + 2/(x + 2) = 1, D = R - {0, -1, -2}. (3) 1/(x - 4) - 8/((x - 4)(x + 4)) = 1/(x + 4), D = R - {4, -4}. (4) (x - 1)/(x + 2) - x/(x + 2) = -1/(x + 2), D = R - {2, -2, 3}. 12) f(x) = (x - 5)/(x - 2) + 3/(x - 2) = 1, D = R - {-4, 2, -2}. f(-2) is undefined, f(5) = 1. 14) base = area / height = (x^2 - 3x - 4)/(x^2 - x - 2) divided by (x^2 - 7x + 12)/(x^2 - 2x) = x/(x - 3). 16) The domain R - {0, 4} means b = 4. f(2) = a/2 + 1/2 = 3 gives a = 5."},{label:"Unit Two Assessment answers (pp. 45-46)",value:"1) x^2 + 4 has no real zeros: the empty set, choice (d). 3) x^2 - 4x + 3 = (x - 1)(x - 3), so the domain is R - {1, 3}, choice (c). 4) f = x(x - 1)/((x - 1)(x + 1)) x x(x + 1)/x^2 = 1, a constant not zero, so the set of zeros is the empty set, choice (a). 5) (x + 1)/(x + 3) = 3/5 gives x = 2, but 2 is not in the domain, so the answer is the empty set. 6) The vertex of f = (x - 3)^2 + 1 is (3, 1). 7) The common domain is R - {-1, 0, 7}. 8) The y-intercept is the point (0, -4). 9) f1 = x^2/(x^2(x - 1)) = 1/(x - 1) and f2 = x(x^2 + x + 1)/(x(x - 1)(x^2 + x + 1)) = 1/(x - 1), both with domain R - {0, 1}, so f1 = f2. 10) f(x) = 1/(x + 2) + 1/(x + 2) = 2/(x + 2), D_f = R - {0, 2, -2} (the values that make a denominator zero: 0, -2, 2). 11) p = (x - 5)(x + 5)/(x(5 - x)) = -(x + 5)/x, so [p]^-1 = -x/(x + 5) with domain R - {5, -5, 0}. 12) f = (x - 1)^2 + 3: vertex (1, 3), axis of symmetry x = 1, opens up, minimum value 3."});re.simpoly=[{label:"Book pages",value:"Lesson 3-1, Similarity of Polygons, book pp. 48-53."},{label:"Definition",value:"Two polygons are similar if BOTH conditions hold together: 1) their corresponding angles are equal in measure, and 2) the lengths of their corresponding sides are proportional: AB/EF = BC/FG = CD/GH = DA/HE = k. Then polygon ABCD ~ polygon EFGH, and k is the similarity ratio of ABCD to EFGH. Write the vertices in the same order of correspondence. The symbol ~ means similar."},{label:"Example 1 from the book",value:"Prove ABCD ~ EFGH: the corresponding angles are equal (A = E, B = F, C = G, D = H), and AB/EF = 12/8 = 3/2, BC/FG = 9/6 = 3/2, CD/GH = 6/4 = 3/2, DA/HE = 15/10 = 3/2. All ratios are equal, so the polygons are similar and the similarity ratio is 3/2."},{label:"Example 2 from the book",value:"Given ABCD ~ EFGH, find missing angles and sides. Corresponding angles are equal: A = E = 90 degrees, B = F = 120 degrees, C = G = 45 degrees. The sum of angles of a quadrilateral is 360, so D = H = 360 - (90 + 120 + 45) = 105 degrees. For sides, use the proportion AB/EF = BC/FG = DC/HG: for example 15 sqrt(3)/(5 sqrt(3)) = 30/FG gives FG = 10 cm, and DC = 30 sqrt(2) cm."},{label:"Special quadrilaterals (Example 3)",value:"All squares are similar. Two rectangles are similar if their corresponding dimensions are proportional (AB/EF = BC/FG). Two rhombuses are similar if two corresponding angles are equal. Two parallelograms are similar if an angle in one equals an angle in the other and the sides around those angles are proportional. Regular polygons with the same number of sides are always similar. Example: rectangles 4 x 6 and 2 x 3 have ratio 2, so they are similar with similarity ratio 2."},{label:"Perimeters of similar polygons",value:"If polygon ABCD ~ polygon EFGH with ratio k, then the perimeter of ABCD / the perimeter of EFGH = k. The ratio between the perimeters of two similar polygons equals the ratio between any two corresponding sides."},{label:"Example 4 from the book",value:"ABCD ~ EFGH and the perimeter ratio is 3/2, so every ratio of corresponding sides is 3/2. From AB/EF = 6/z = 3/2, z = 4. From BC/FG = (y + 3)/5 = 3/2, y + 3 = 7.5, y = 4.5. From CD/GH = (2x + 1)/(x + 2) = 3/2: 4x + 2 = 3x + 6, so x = 4."},{label:"Lesson assessment answers (pp. 52-53, those that use numbers only)",value:"2) Rectangles are similar: 36/24 = 27/x, so x = 18, choice (c). 4) Two squares with perimeter ratio 3/2 have side ratio 3/2. The side of ABCD is 6, so the side of XYZM is 4 and its area is 16 cm^2, choice (c). 7) Side ratio 2 : 3, so the perimeter ratio is 2 : 3. If the smaller perimeter is 34 then the larger is 34 x 3/2 = 51 cm, choice (c). 8) Nourhan is correct: regular polygons are similar only if they have the same number of sides (a regular triangle and a square are not similar). 12) The first polygon has perimeter 3 + 5 + 6 + 8 + 10 = 32. The ratio is 80/32 = 2.5, so the sides of the other polygon are 7.5, 12.5, 15, 20 and 25 cm."},{label:"Opening problem",value:"The statue is 195 cm high and 58 cm wide. A model that is 5 cm wide has the scale 5/58, so its height is 195 x 5/58 = about 16.8 cm."},{label:"Tip for the exam",value:"To prove similarity you need BOTH conditions: equal angles and proportional sides. Always match sides by the order of the letters (AB with EF, BC with FG)."}];re.simtri=[{label:"Book pages",value:"Lesson 3-2, Similarity of Triangles, book pp. 54-61."},{label:"Case 1: AA (two angles)",value:"If two angles in one triangle are equal to two angles in another triangle, the triangles are similar. If m(A) = m(D) and m(B) = m(E) then triangle ABC ~ triangle DEF. Then the third angles are equal too, and AB/DE = BC/EF = AC/DF."},{label:"Case 2: SSS (three sides)",value:"If the lengths of the corresponding sides of two triangles are proportional, the triangles are similar: AB/DE = BC/EF = AC/DF means triangle ABC ~ triangle DEF. Then all corresponding angles are equal."},{label:"Case 3: SAS (two sides and the included angle)",value:"If one angle of a triangle equals an angle of another, and the sides containing these angles are proportional, the triangles are similar. Example: m(C) = m(F) and AC/DF = BC/EF give triangle ABC ~ triangle DEF."},{label:"Note",value:"If triangle 1 ~ triangle 2 and triangle 1 ~ triangle 3, then triangle 2 ~ triangle 3."},{label:"Example 1 from the book",value:"AB parallel to DC, AC and BD meet at E. AB = 6, AE = 7.5, DC = 4, BD = 7. Alternate angles give m(A) = m(C) and m(B) = m(D), so triangle ABE ~ triangle CDE (case AA). Then AB/CD = BE/DE = AE/CE: 6/4 = 7.5/CE gives CE = 5 cm. With BE + DE = 7: 6/4 = (7 - DE)/DE, 6DE = 28 - 4DE, DE = 2.8 cm and BE = 4.2 cm."},{label:"Example 2 from the book",value:"Prove triangle ABC ~ triangle ADE: AB/AD = (4.5 + 3.5)/4 = 2, BC/DE = 6/3 = 2, AC/AE = (4 + 5)/4.5 = 2. All three ratios are equal, so the triangles are similar (SSS) and the similarity ratio of ABC to ADE is 2."},{label:"Example 3 from the book",value:"m(ACB) = m(DCE), AC/DC = 9/6 = 3/2 and BC/EC = 12/8 = 3/2. Two sides proportional with the included angle equal (SAS), so triangle ABC ~ triangle DEC and AB/DE = 3/2, AB = 3 x 10/2 = 15 cm."},{label:"Similarity in right-angled triangles",value:"If triangle ABC is right-angled at C and CD is perpendicular to AB, then CD divides the triangle into two triangles similar to each other and to the original: triangle ACB ~ triangle ADC ~ triangle CDB (use AA with the right angle and the common angle). Example 4: In a triangle right-angled at A with AD perpendicular to BC, triangle ADB ~ triangle CDA, so AD/CD = DB/DA, and (AD)^2 = BD x DC."},{label:"Example 5 (real life)",value:"A student 1.6 m tall has a 1.5 m shadow. The flagpole has a 2.4 m shadow. The sun makes equal angles, and the right angles are equal, so the two triangles are similar: 1.5/2.4 = 1.6/h, so h = 2.4 x 1.6/1.5 = 2.56 m."},{label:"Opening problem and Think & Discuss",value:"Palm tree: stick 2 m with a 1.2 m shadow, palm shadow 3.6 m. 2/h = 1.2/3.6, so h = 6 m. In the Think and Discuss box, DE = 4 and BC = 14 with DE parallel to BC: the ratio is 4/14 = 2/7, so the perimeter of triangle AED is 49 x 2/7 = 14 cm. Maryam is correct."},{label:"Selected assessment answers (pp. 59-61)",value:"12) Right angle at B, BD perpendicular to AC. Triangle ADB ~ triangle BDC, so AD/BD = BD/DC. AB = 8 (3-4-5 triangle scaled: 6.4, 4.8, 8). DC = BD^2/AD = 4.8^2/6.4 = 3.6 cm. 13) AB parallel to DE and BC parallel to EF give equal corresponding angles, so triangle ABC ~ triangle DEF. If EF : BC = 3 : 2, the perimeter of DEF = 24 x 3/2 = 36 cm. 14) AB^2 = BD x BC when triangle ABD ~ triangle CBA: 144 = 8 x BC, BC = 18, so DC = 10 matches the figure. 15) The man (1.9 m) is 2 m from the mirror and the mirror is 12 m from the statue. The angles at the mirror are equal, so the triangles are similar: h/1.9 = 12/2, h = 11.4 m. 16) KL parallel to PQ parallel to MN: PQ = (KL x MN)/(KL + MN) = 150/25 = 6 cm."},{label:"Tip for the exam",value:"Choose the case that fits your data: two angles (AA), three sides (SSS) or two sides with the included angle (SAS). Write the similarity with the letters in the correct order, then write the three equal ratios before solving."}];re.dilation=[{label:"Book pages",value:"Lesson 3-3, Dilation, book pp. 62-67."},{label:"Concept",value:"A dilation is a geometric transformation that enlarges or reduces a figure by a specific ratio, called the dilation factor. The figure and its image are similar: angles stay the same, and the lengths of corresponding sides change by a constant ratio. In this book we study positive dilation factors only."},{label:"Definition",value:"A dilation with center C and factor k maps each point P to a point the image point P′ such that: 1) the center C maps to itself, 2) if P is not C, then CP′ = k x CP and P′ lies on ray CP. If k > 1 the dilation is an enlargement (P lies on segment CP′). If 0 < k < 1 it is a reduction (P′ lies on segment CP). The dilation factor k = side in the image / corresponding side in the original = distance of the image point from the center / distance of the original point from the center."},{label:"Properties",value:"Triangle PQR ~ triangle P′Q′R′, and each side of the image is parallel to its corresponding side in the original figure. Example: factor 5/2 is an enlargement and factor 1/2 is a reduction."},{label:"Example 1 from the book",value:"Q′ is the image of Q under a dilation with center C. CQ′ = 15 and CQ = 5, so k = 15/5 = 3 and it is an enlargement. The matching side gives x/4 = 3, so x = 12."},{label:"Example 2 from the book",value:"Triangle ADE is the image of triangle ABC under a dilation with center A. D is the image of B, so k = AD/AB = 9/15 = 3/5 (a reduction). DE is parallel to BC because a side and its image are parallel. DE/BC = k, so 7.5/BC = 3/5 and BC = 12.5 cm."},{label:"Dilation in the coordinate plane",value:"Dilation with center at the origin O and factor k: (x, y) goes to (kx, ky). Example 3: triangle ABC with A(1, 3), B(2, -1), C(5, 0) and k = 2 gives A′(2, 6), B′(4, -2), C′(10, 0). It is an enlargement, the image is similar to ABC, and each side is parallel to its original side. Example 4: polygon with A(-3, 6), B(0, 6), C(3, 3), D(-3, -3) and k = 1/3 gives A′(-1, 2), B′(0, 2), C′(1, 1), D′(-1, -1). Since 0 < k < 1 it is a reduction."},{label:"Assessment answers (p. 65)",value:"1) C, P, P′ on a line with CP = 1 and PP′ = 3, so CP′ = 4 and k = CP′/CP = 4, choice (d). 2) A′B′ is the image of AB: A′B′ = 3 and AB = 4, so k = 3/4, choice (a)."},{label:"Opening problem and Think & Discuss",value:"The rabbit model is 20 cm tall, 24 cm from the light and 36 cm from the wall, so the wall is 24 + 36 = 60 cm from the light. The image height = 20 x 60/24 = 50 cm. In Think and Discuss, to enlarge a figure with ratio 2 : 1, multiply each coordinate of every vertex by 2."},{label:"Tip for the exam",value:"Dilation factor = image / original. If k > 1 enlargement, if 0 < k < 1 reduction. Centre at the origin: multiply both coordinates by k."}];re.dilation.push({label:"Assessment answers (pp. 66-67)",value:"4) P(-1, 3) with k = 4 gives P′(-4, 12), choice (c). 5) A(6, -2) to B(3, -1): k = 3/6 = 1/2, choice (c). 6) To map A′ back to A the factor is the reciprocal 4/3, choice (b). 7) A′(12, -6) = (3/2 x, 3/2 y), so x = 8 and y = -4: A(8, -4), choice (a). 8) A reduction needs 0 < k < 1, so 50% = 1/2, choice (d). 12) Actual length 2.5 mm, image 3.75 cm = 37.5 mm, so k = 37.5/2.5 = 15 (enlargement). 13) The image has sides x/3 and y/3, so its area is xy/9."});re.ratios=[{label:"Book pages",value:"Lesson 3-4, Trigonometric Ratios of an Acute Angle, book pp. 68-73."},{label:"The three ratios",value:'In a right-angled triangle, for an acute angle θ: sin θ = opposite / hypotenuse, cos θ = adjacent / hypotenuse, tan θ = opposite / adjacent. Example: triangle with sides 3, 4, 5: sin = 3/5, cos = 4/5, tan = 3/4. Also tan θ = sin θ / cos θ. θ is read "theta" and β "beta". Pythagoras: c^2 = a^2 + b^2 (c is the hypotenuse).'},{label:"Complementary angles",value:"For two complementary angles θ and β (sum 90 degrees): sin θ = cos β and cos θ = sin β. Example 1: triangle with legs 12 and 5, hypotenuse 13: sin θ = 5/13, cos θ = 12/13, tan θ = 5/12, and for β: sin β = 12/13, cos β = 5/13, tan β = 12/5."},{label:"Example 2 from the book",value:"sin θ = 3/5, hypotenuse AC = 10. Then x = BC = 10 x 3/5 = 6. By Pythagoras y = AB = sqrt(100 - 36) = 8. cos θ = 8/10 = 4/5 and tan θ = 6/8 = 3/4. So sin^2 θ + cos^2 θ - tan θ = 9/25 + 16/25 - 3/4 = 1 - 3/4 = 1/4. (Note: sin^2 θ + cos^2 θ = 1 always.)"},{label:"Example 3: given one ratio",value:"cos θ = 12/13. Assume BC = 12k and AC = 13k. Then AB = sqrt(169k^2 - 144k^2) = 5k. So sin θ = 5/13 and tan θ = 5/12 (also tan θ = sin θ / cos θ). If BC = 24 cm then k = 2: AC = 26 cm and AB = 10 cm."},{label:"Example 4 from the book",value:"tan θ = 3/4. In triangle ADE (right angle at D): ED/AD = x/8 = 3/4, so x = 6. In triangle ABC (right angle at B): tan θ = 12/(y + 8) = 3/4, so y + 8 = 16 and y = 8."},{label:"Assessment answers (pp. 71-73, ones that do not depend on the figure labels)",value:"2) tan X with legs 40 and 9 and hypotenuse 41: opposite 9, adjacent 40, tan X = 9/40, choice (c). 3) sin θ = 1/2, cos θ = sqrt(3)/2, so tan θ = 1/sqrt(3), choice (c). 4) A and B are complementary, so cos B = sin A = 12/13, choice (a). 5) 26 AB = 10 AC means AB/AC = 5/13. Take AB = 5k, AC = 13k, BC = 12k. tan C = AB/BC = 5/12, choice (b). 11) Spot the mistake: tan A = BC/AB = 1/2 with BC = 5, so AB = 10 and AC = 5 sqrt(5). Wael is correct. Sarah used AB/BC, which is wrong. 13) sin θ = 1/3: cos θ = 2 sqrt(2)/3, tan θ = 1/(2 sqrt(2)) = sqrt(2)/4, cos β = sin θ = 1/3, tan β = 2 sqrt(2). 14) tan θ = 1/sqrt(3) means θ = 30 degrees, so with the hypotenuse AC = 10 sqrt(3): BC = 5 sqrt(3) cm and AB = 15 cm. 16) A triangle with AB = 15, BC = 20, AC = 25 (right angle at B): tan A x tan C = (20/15)(15/20) = 1. Also sin A = 4/5 and cos A = 3/5, so sin^2 A + cos^2 A = 1."},{label:"Opening problem",value:"The kite string is 10 m and sin θ = 3/5 (AB/AC = 3/5). The height of the kite above the person's hand is 10 x 3/5 = 6 m."},{label:"Tip for the exam",value:"Label the sides first: opposite, adjacent, hypotenuse (relative to the angle). If you are given one ratio, assume the two sides as 3k and 5k type multiples, find the third side with Pythagoras, then read the other ratios."}];re.special=[{label:"Book pages",value:"Lesson 3-5, Trigonometric Ratios of Some Special Angles, book pp. 74-79."},{label:"Special angles table",value:"30 degrees: sin = 1/2, cos = sqrt(3)/2, tan = 1/sqrt(3) = sqrt(3)/3. 60 degrees: sin = sqrt(3)/2, cos = 1/2, tan = sqrt(3). 45 degrees: sin = 1/sqrt(2) = sqrt(2)/2, cos = 1/sqrt(2) = sqrt(2)/2, tan = 1. They come from the 30-60-90 triangle (sides 1, sqrt(3), 2) and the 45-45-90 triangle (sides 1, 1, sqrt(2))."},{label:"Example 1 from the book",value:"1) cos 45 = x/16, so x = 16/sqrt(2) = 8 sqrt(2). 2) tan 30 = 4/x, so 1/sqrt(3) = 4/x and x = 4 sqrt(3). 3) sin 60 = 20 sqrt(3)/x, so sqrt(3)/2 = 20 sqrt(3)/x and x = 40."},{label:"Using the calculator",value:"Use the sin, cos and tan keys. Check the calculator is in degree mode. 1 degree = 60 minutes and 1 minute = 60 seconds. Example 2: sin 42 is about 0.6691, cos 15 17 minutes is about 0.9646, tan 74 12 minutes 36 seconds is about 3.5363. Example 3 (to 2 decimals): tan 54 = 6/x gives x = 6/tan 54, about 4.36. sin 26 = x/8 gives x = 8 sin 26, about 3.51."},{label:"Finding an angle from its ratio",value:"If sin θ = x then θ = sin^-1(x). If cos θ = x then θ = cos^-1(x). If tan θ = x then θ = tan^-1(x). Use SHIFT then the key. Example: sin θ = 0.834 gives θ of about 56 degrees 30 minutes 43 seconds. Example 4: tan θ = 2/3 gives θ of about 33 degrees 41 minutes 24 seconds. sin θ = 2/sqrt(5) gives θ of about 63 degrees 26 minutes 6 seconds."},{label:"Examples 5 and 6",value:"Example 5: 2 cos(θ + 20) = tan 45 = 1, so cos(θ + 20) = 1/2, θ + 20 = 60 and θ = 40. Rule: if sin θ = cos β then θ + β = 90 degrees. Example 6: in triangle ABC with B = 72 degrees and sin A = cos 2A: A + 2A = 90, so A = 30 and C = 180 - (72 + 30) = 78 degrees."},{label:"Assessment answers (p. 77, multiple choice)",value:"1) sin 40 = cos y gives y = 50, choice (c). 2) sin^2 30 + cos^2 30 = 1 = tan 45, choice (c). 3) Isosceles right triangle at C: tan B = 1, choice (a). 4) A = 70 and cos B = sin B give B = 45, so C = 65, choice (a). 5) sin(θ - 10) = 1/sqrt(2) gives θ - 10 = 45 and θ = 55, choice (b). 6) sin 4θ = sqrt(3)/2 gives 4θ = 60 and θ = 15, choice (a)."},{label:"Assessment answers (pp. 78-79, selected)",value:"9) 1: x tan 45 cos 30 = tan 60 gives x(sqrt(3)/2) = sqrt(3), so x = 2. 2: x sin 45 cos 45... check the printed expression in the book; with x sin 45 tan 60 = (tan 45)^2 - (cos 60)^2: x (sqrt(2)/2)(sqrt(3)) = 3/4, so x = sqrt(6)/4. 10) 1: cos 4θ = 1/2, so 4θ = 60 and θ = 15. 2: tan 3θ = sqrt(3), so 3θ = 60 and θ = 20. 3: cos 4θ = sin 2θ, so 4θ + 2θ = 90 and θ = 15. 16) Ramp height = 10 sin 16, about 2.76 m. 17) Distance = 180 / tan 33, about 277.17 m. For the figure-based items 7, 8, 11-15 and 18, apply the same steps (sin, cos or tan of the given angle) and check the figure in your book."},{label:"Tip for the exam",value:"Memorise the table for 30, 45 and 60. If the unknown is opposite and you know the hypotenuse use sin; adjacent and hypotenuse use cos; opposite and adjacent use tan."}];re.perp=[{label:"Book pages",value:"Lesson 3-6, The Relation between the Slopes of Two Parallel and Perpendicular Straight Lines, book pp. 80-85."},{label:"Inclination angle and slope",value:"The inclination angle θ of a line is the angle it makes with the positive direction of the x-axis, measured anti-clockwise. The slope is m = tan θ. Through two points: m = (y2 - y1)/(x2 - x1). Slope positive when 0 < θ < 90, negative when 90 < θ < 180, zero for a horizontal line (θ = 0) and undefined for a vertical line (θ = 90). Examples: tan 60 = sqrt(3); tan 150 = -sqrt(3)/3."},{label:"Example 1 and 2",value:"1) m = 3/7 gives θ = tan^-1(3/7), about 23 degrees 11 minutes 55 seconds. For the points (5, 6) and (4, 7): m = (6 - 7)/(5 - 4) = -1. For a negative slope, θ = 180 + tan^-1(-1) = 135 degrees. Example 2: A(2k + 1, -5), B(-3, k) with inclination 45: slope = 1, so (-5 - k)/(2k + 4) = 1, 2k + 4 = -5 - k, 3k = -9, k = -3."},{label:"Parallel lines",value:"If two non-vertical lines are parallel then m1 = m2, and the converse is true. Any two vertical lines are parallel. Example 3: A(2, 1), B(4, -1) has slope (1 + 1)/(2 - 4) = -1, and a line with inclination 135 has slope tan 135 = -1, so they are parallel. Example 4: collinear points A(4, 3), B(2, 7), C(8, -5): slope AB = (7 - 3)/(2 - 4) = -2 and slope AC = (3 + 5)/(4 - 8) = -2, A is common, so A, B, C are collinear."},{label:"Perpendicular lines",value:"If l1 is perpendicular to l2 then m1 x m2 = -1, and the converse is true. If one line is vertical the other is horizontal. If the slope of a line is a/b the slope of the perpendicular is -b/a. Example 5: line through (-1, 6),(5, 2) has slope -2/3 and line through (6, 8),(-2, -4) has slope 12/8 = 3/2. The product is -1, so they are perpendicular."},{label:"Example 6: prove a rectangle",value:"A(0, -1), B(-3, 2), C(-1, 4), D(2, 1). Slope AB = -1 and slope CD = -1, so AB is parallel to CD. Slope AD = 1 and slope CB = 1, so AD is parallel to CB. So ABCD is a parallelogram. Slope AB x slope AD = -1, so AB is perpendicular to AD, and ABCD is a rectangle. To prove a rhombus or square, also use the equal sides or perpendicular diagonals."},{label:"Assessment answers (pp. 83-84, multiple choice)",value:"1) (c) -2/3. 2) slope through (6, 3) and (-2, -4) is 7/8, so the perpendicular slope is -8/7, choice (c). 3) tan 60 = sqrt(3), choice (c). 4) a line perpendicular to the x-axis is vertical, its slope is undefined, choice (d). 5) -5/3 = k/6 gives k = -10, choice (b). 6) slope AB = (0 - 4)/(4 - 2) = -2, so BC has slope 1/2, choice (c). 7) In a square BC is perpendicular to AB, so slope = -1/sqrt(3) = -sqrt(3)/3, choice (d). 8) The diagonals of a rhombus are perpendicular, so slope AC = -4/3, choice (a)."},{label:"Tip for the exam",value:"Parallel: equal slopes. Perpendicular: product of slopes = -1. Collinear: equal slopes from a common point. Always compute the slope as (y2 - y1)/(x2 - x1) with the same order for both points."}];re["line-eq"]=[{label:"Book pages",value:"Lesson 3-7, Equation of the Straight Line, book pp. 86-93."},{label:"Slope and y-intercept form",value:"y = mx + b, where m is the slope and b is the y-intercept (the line meets the y-axis at (0, b)). A line through the origin: y = mx. Example: slope 4/5 and y-intercept -3 gives y = (4/5)x - 3."},{label:"Special lines",value:"x-axis: y = 0. y-axis: x = 0. A line through (x1, y1) parallel to the x-axis: y = y1. A line through (x1, y1) parallel to the y-axis: x = x1."},{label:"Slope and a point",value:"A line with slope m through C(x1, y1): y - y1 = m(x - x1). Example: slope 2/3 through (3, 4): y - 4 = (2/3)(x - 3)."},{label:"Example 1",value:"1) Inclination 135 so m = tan 135 = -1, y-intercept -4: y = -x - 4. 2) Through the origin and perpendicular to y = -2x + 3 (slope -2): the slope is 1/2, so y = (1/2)x."},{label:"Example 2: graphing",value:"Slope 3/2 and y-intercept 1 gives y = (3/2)x + 1. Plot (0, 1), then move 2 units right and 3 units up, and join the points."},{label:"Example 3: two points",value:"Through (-4, 5) and (4, 1): m = (1 - 5)/(4 + 4) = -1/2. Then y - 1 = (-1/2)(x - 4), so y = (-1/2)x + 3. Using the other point gives the same equation."},{label:"Standard form",value:"Ax + By = C, where A is zero or positive, A and B are not both zero, and A, B, C are integers with greatest common factor 1. Slope = -A/B, y-intercept = C/B, x-intercept = C/A. Example: 2x + 3y = 6 has slope -2/3, y-intercept 2 and x-intercept 3."},{label:"Example 4",value:"Through (-4, 3) and perpendicular to 4x + y + 1 = 0: the given slope is -4, so the required slope is 1/4. y - 3 = (1/4)(x + 4), 4y - 12 = x + 4, so x - 4y = -16."},{label:"Example 5",value:"The line through (7, -9) and (3, 3) has slope (-9 - 3)/(7 - 3) = -3. The line 2x + ky - 16 = 0 has slope -2/k. Perpendicular: (-3)(-2/k) = -1, so 6/k = -1 and k = -6."},{label:"Example 6: distance-time graph",value:"Read the speed as the slope of the distance-time line (change in d divided by change in t). The distance at t = 0 is the d-intercept. The equation is d = (speed) t + (initial distance). Substitute t = 3 to find the distance after 3 hours. Check the numbers on the graph in your book."},{label:"Tip for the exam",value:"Find the slope first (from two points, an angle, or parallel/perpendicular), then use y - y1 = m(x - x1). Convert to Ax + By = C at the end if the question asks for the standard form."}];re["line-eq"].push({label:"Assessment answers, multiple choice (p. 90)",value:"1) 2x - y - 5 = 0 gives y = 2x - 5, y-intercept -5, choice (a). 2) 3x - 4y = 7 has slope 3/4, choice (c). 3) perpendicular slope = -4/3, choice (a). 4) slope through (-1, 4) and (-4, 5) = -1/3, y = (-1/3)x + 11/3, choice (a). 5) slopes k/3 and (k - 1)/2 are equal: 2k = 3k - 3, k = 3, choice (a). 6) inclination 45 gives slope 1; kx + 2y = 5 has slope -k/2, and perpendicular means -k/2 = -1, so k = 2, choice (c). 7) perpendicular slope -3 through the origin: y = -3x, choice (b). 8) y - sqrt(3)x + 5 = 0 has slope sqrt(3), so the angle is 60, choice (c). 9) parallel to the y-axis through (-2, 1): x = -2, choice (a). 10) 5x - 6y - 30 = 0 has x-intercept 6 and y-intercept -5, area = (1/2)(6)(5) = 15, choice (b)."},{label:"Assessment answers, problems 11-13 (p. 91)",value:"11) (1) -2x + 5y = 20: slope 2/5, y-intercept 4, x-intercept -10. (2) 4x - 2y + 8 = 0: slope 2, y-intercept 4, x-intercept -2. (3) y = 7x: slope 7, both intercepts 0. (4) y = (-2/3)x - 4: slope -2/3, y-intercept -4, x-intercept -6. 12) (1) y = -2x + 3. (2) the line passes through (-2, 0) with slope 5/2: y = (5/2)x + 5. (3) y = (1/2)x + 1. (4) slope = (-4 - 1)/(8 - 6) = -5/2, y = (-5/2)x + 16. (5) perpendicular to y = x - 2 through (0, -2): y = -x - 2. (6) parallel to 2x + 5y = 10 (slope -2/5) through (-1, 2): y = (-2/5)x + 8/5. 13) (1) 4x + 3y = 12. (2) the slope through (5, -3) and (2, 4) is -7/3, so the line is y = (-7/3)x, in standard form 7x + 3y = 0. (3) the midpoint of AB is (5, 1) and the slope of AB is -4/3, so the required slope is 3/4: 3x - 4y = -11."},{label:"Assessment answers, problems 14-19",value:"14) (1) y = 2. (2) the line passes through (-4, 0) and (0, 7): y = (7/4)x + 7. (3) the line passes through (4, 3) and (7, -2): 5x + 3y = 29. 16) slope BC = (10 - 4)/(-6 - 6) = -1/2, so AD has slope 2: y + 8 = 2(x + 6), y = 2x + 4. 17) y = 1.5x + 25. 18) slope = (120 - 100)/(1400 - 1000) = 0.05, so y = 0.05x + 50, and at x = 2000 the earnings are 150 EGP. Items 14(4), 15, 19 and 20 depend on figures: check the book."});re["line-eq"].push({label:"Unit Three Assessment answers (p. 93)",value:"1) tan X sin 30 = cos 30: tan X (1/2) = sqrt(3)/2, so tan X = sqrt(3) and X = 60, choice (c). 2) 2y = x - 4 has slope 1/2 = tan θ, choice (b). 3) P(-3, 6) maps to P′(-2, 4): k = 2/3, choice (c). 5) 2x - 3y - 3 = 0 has slope 2/3. 6) A = (4, 8). 7) AB = 12, BC = 5, AC = 13: sin A = 5/13 and cos C = 5/13, so the sum is 10/13. 8) ABCD is similar to EHGF, so AB/EH = BC/HG: 8/12 = x/6 and x = 4. Item 4 depends on the figure: check the book."});re["stats-disp"]=[{label:"Book pages",value:"Lesson 4-1, Measures of Dispersion, book pp. 96-105."},{label:"Why dispersion?",value:"Measures of central tendency (mean, median, mode) describe the centre of the data. Two groups can have the same mean, median and mode but different spread, for example 33, 33, 33, 27, 24 and 43, 35, 33, 33, 6 (mean 30, median 33, mode 33 for both). Measures of dispersion show how close or far the values are from the centre. The smaller the dispersion, the more consistent (homogeneous) the data. If all values are equal, the dispersion is zero."},{label:"Range",value:"Range R = greatest value - smallest value. It is the simplest measure, depends only on two values and is affected by extreme values. Example 1 from the book: 48, 61, 65, 52, 38, 64, 66, 64 gives R = 66 - 38 = 28. From a box plot from 16 to 48: R = 32. From a dot plot from 10 to 70: R = 60. From a stem-and-leaf plot, read the smallest and the greatest value (with the key). Example 2: find k so that the range of 17, 12, 19, k, 18, 15, 11 equals 13. The smallest is 11 and the greatest is 19. If 11 <= k <= 19 the range is 8 (refused). If k > 19 then k - 11 = 13, so k = 24. If k < 11 then 19 - k = 13, so k = 6."},{label:"Interquartile range (IQR)",value:"IQR = Q3 - Q1, the range of the middle half of the data. It is more accurate when there are extreme values, but it ignores the other values. Steps: arrange the values in ascending order, find the median Q2, then Q1 is the median of the lower half and Q3 the median of the upper half. Example 3: 23, 20, 19, 12, 6, 9, 16, 23, 10, 18, 5 sorted is 5, 6, 9, 10, 12, 16, 18, 19, 20, 23, 23. Q1 = 9, Q2 = 16, Q3 = 20, IQR = 20 - 9 = 11. Example 4 (box plots): first exam Q1 = 8, Q3 = 22, IQR = 14. Second exam Q1 = 6, Q3 = 16, IQR = 10."},{label:"Standard deviation of a set of values",value:"σ = sqrt( sum of (x - mean)^2 / n ). It is the most important and accurate measure. The smaller σ is, the closer the values are to each other (more homogeneous). Steps: find the mean, make a table of x, (x - mean) and (x - mean)^2, add the last column, divide by n, take the square root. Example 5: 13, 15, 17, 18, 12: mean = 75/5 = 15. Deviations -2, 0, 2, 3, -3. Squares 4, 0, 4, 9, 9, total 26. σ = sqrt(26/5), about 2.28."},{label:"Simple frequency distribution",value:"σ = sqrt( sum f (x - mean)^2 / sum f ), where mean = sum f x / sum f. Example 6: ages 2, 5, 10, 12, 16, 34 with frequencies 1, 2, 5, 2, 3, 1 (14 people). Sum f x = 168, so the mean = 12. Sum f (x - mean)^2 = 750. σ = sqrt(750/14), about 7.32."},{label:"Frequency distribution with intervals",value:"Use the centre of each interval, xm = (lower limit + upper limit)/2, in the same formula. Example 7: masses 60-, 70-, 80-, 90-, 100- with frequencies 5, 11, 18, 9, 7 (50 people). Centres 65, 75, 85, 95, 105. Sum f xm = 4270, mean = 85.4. Sum f (xm - mean)^2 = 6792. σ = sqrt(6792/50), about 11.66."},{label:"Calculator",value:"Standard deviation on a scientific calculator: SHIFT, MODE (SETUP), STAT, 1-VAR. Enter the values (centres) in the x column and the frequencies in FREQ, press AC, then SHIFT, 1 (STAT), VAR, then the σx key. The book example gives 11.66."},{label:"Lesson assessment answers: multiple choice (pp. 102)",value:"1) Median is not a measure of dispersion, choice (c). 3) range = 23 - 11 = 12 thousand = 12000, choice (c). 4) IQR = Q3 - Q1, so Q3 = 29 + 8.5 = 37.5, choice (c). 6) sum (x - mean)^2 = 36 and n = 9, so σ = sqrt(4) = 2, choice (d). 7) all values equal, σ = 0, choice (a). 8) range 4.6: the smallest is 35.2, so the greatest is 39.8 and k = 8; m is the stem 37, so k + m = 45, choice (c). 9) values 55, 61, 56, 59, a, 54 with range 9: a = 52 gives max 61 and min 52, range 9, choice (d). Items 2 and 5 depend on the figures: check the book."},{label:"Lesson assessment answers: problems 10-15 (pp. 103)",value:"10) Hany is correct. Wael wrongly squared the signed deviations as negative numbers, so his total became 0. Hany: sum = 40, σ = sqrt(40/5) = sqrt(8) = 2 sqrt(2). 11) (1) the values 24, 25, 17, 16, 20 give 25 - 16 = 9. (2) 76 - 41 = 35. (3) smallest 04, greatest 27: range 23. 12) (1) sorted 16, 17, 25, 29, 33, 34, 46: Q1 = 17, Q3 = 34, IQR = 17. (2) sorted 1.2, 2.1, 2.3, 3.7, 5.1, 5.4, 8.4: Q1 = 2.1, Q3 = 5.4, IQR = 3.3. 13) (1) mean 15, sum of squares 28, σ = sqrt(28/6), about 2.16. (2) same spread as 5, 2, 7, 8, 3: mean 5, sum of squares 26, σ = sqrt(26/5), about 2.28. (3) values 22, 22, 25, 27, 33, 35, 38, 40, 40, 48: mean 33, sum of squares 694, σ = sqrt(69.4), about 8.33. 14) values 12, 14, 15, 19: mean 15, sum of squares 26, σ = sqrt(6.5), about 2.55. 15) (2x + 18)/5 = x gives x = 6. Values 7, 6, 8, 4, 5: mean 6, sum of squares 10, σ = sqrt(2), about 1.41."},{label:"Lesson assessment answers: problems 16-21 (p. 104)",value:"16) Handball team: 184 (1 student), 186 (4), 188 (3), 189 (2): mean = 1870/10 = 187 cm and σ = sqrt(24/10), about 1.55 cm. The basketball team has mean 187 and σ = 7. The means are equal, and the handball team has the smaller σ, so its heights are more homogeneous. 17) n = 30, sum = 540, mean = 18 GB, sum f (x - mean)^2 = 398, σ = sqrt(398/30), about 3.64 GB. 18) centres 125, 135, 145, 155, 165, 175 with frequencies 18, 21, 20, 15, 16, 10 (100 workers): mean = 14700/100 = 147 pounds, sum f (xm - mean)^2 = 25800, σ = sqrt(258), about 16.06 pounds. 19) five consecutive even numbers have deviations -4, -2, 0, 2, 4, so σ = sqrt(40/5) = sqrt(8), choice (d). 20) deviations 2x, -x, 0, x, -2x give σ = x sqrt(2) = 4 sqrt(2), so x = 4, choice (d). 21) seven consecutive numbers have σ = sqrt(28/7) = 2 = sqrt(k)/3, so sqrt(k) = 6 and k = 36, choice (c)."},{label:"Unit Four Assessment answers (p. 105)",value:"1) smallest 26.1, greatest 29.3, range 3.2, choice (c). 2) range = (7 + 6k) - (7 - 3k) = 9k = 18, so k = 2, choice (b). 3) the integers 3, 4, 5, 6, 7 have σ = sqrt(2), choice (b). 4) the largest spread is 16, 20, 6, 2, choice (d). 5) range = 61 - 17 = 44. 7) the values 17 - b, 15 - b, 12 - b, 16 - b have the same σ as 17, 15, 12, 16: mean 15, sum of squares 14, σ = sqrt(3.5), about 1.87. 8) σ = sqrt(60/12) = sqrt(5). 9) n = 30, sum f x = 90, mean = 3 goals, sum f (x - mean)^2 = 72, σ = sqrt(72/30), about 1.55. 10) the range is 20, so x + 15 - 2 = 20 and x = 7. 11) sorted 5, 15, 17, 18, 21, 22, 29: Q1 = 15, Q3 = 22, IQR = 7. Items 6 and 12 depend on figures: check the book."},{label:"Tip for the exam",value:"Range for a quick spread, IQR when there are extreme values, and σ for the most accurate comparison. Smaller σ means more consistent data. For frequency tables remember to multiply by f in every sum."}];const Qe="https://gzgsiwnzvysaqyjghxkc.supabase.co/rest/v1/rpc/",Ve="sb_publishable_T0EXp8Zma47jhXFkoTKp8A_Q49_LOFE";async function ve(a,t){const i=await fetch(Qe+a,{method:"POST",headers:{apikey:Ve,"Content-Type":"application/json"},body:JSON.stringify(t)});if(!i.ok)throw new Error("rpc "+i.status);return i.json()}const Ye=(a,t)=>ve("create_student",{p_name:a,p_grade:t}),Fe=a